// Flatten dimensions into one sheet row each.
const hc = $('TeamRetro Trigger').first().json.data.healthCheck;
return $input.all().map(({ json: dim }) => ({
  json: {
    date: hc.date,
    team: hc.team?.name ?? '',
    healthCheck: hc.title,
    dimension: dim.name,
    score: dim.ratings?.average ?? dim.ratings?.score ?? null,
  },
}));
